describe('Dynamic Content Updates Accessibility', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.injectAxe();
  });

  it('should announce dynamic content updates to screen readers using aria-live regions', () => {
    // Verify aria-live region exists
    cy.get('[aria-live="polite"]').should('exist');

    // Trigger dynamic content update
    cy.get('[data-testid="update-button"]').click();

    // Verify content is updated
    cy.get('[data-testid="dynamic-content"]').should('contain', 'Content Updated');

    // Verify aria-live region contains the update
    cy.get('[aria-live="polite"]').should('contain', 'Content Updated');

    // Run accessibility checks
    cy.checkA11y();
  });

  it('should properly announce urgent updates with aria-live="assertive"', () => {
    // Verify assertive aria-live region exists for urgent updates
    cy.get('[aria-live="assertive"]').should('exist');

    // Trigger urgent update
    cy.get('[data-testid="urgent-update-button"]').click();

    // Verify urgent content is announced
    cy.get('[aria-live="assertive"]').should('contain', 'Urgent Update');

    // Verify role="alert" is present for critical announcements
    cy.get('[role="alert"]').should('exist');
    cy.get('[role="alert"]').should('contain', 'Urgent Update');
  });

  it('should announce loading states and completion messages', () => {
    // Verify aria-busy attribute during loading
    cy.get('[data-testid="async-content"]').should('have.attr', 'aria-busy', 'false');

    // Trigger async operation
    cy.get('[data-testid="load-button"]').click();

    // Verify loading state is announced
    cy.get('[data-testid="async-content"]').should('have.attr', 'aria-busy', 'true');
    cy.get('[aria-live="polite"]').should('contain', 'Loading');

    // Wait for completion
    cy.get('[data-testid="async-content"]', { timeout: 10000 }).should('have.attr', 'aria-busy', 'false');

    // Verify completion message is announced
    cy.get('[aria-live="polite"]').should('contain', 'Loaded');
  });

  it('should maintain aria-live regions without clearing previous announcements prematurely', () => {
    // Get initial aria-live region
    const ariaLiveRegion = cy.get('[aria-live="polite"]');

    // Trigger first update
    cy.get('[data-testid="update-button"]').click();
    ariaLiveRegion.should('contain', 'First Update');

    // Trigger second update quickly
    cy.get('[data-testid="update-button"]').click();
    ariaLiveRegion.should('contain', 'Second Update');

    // Verify both announcements are accessible
    cy.get('[aria-live="polite"]').invoke('text').then((text) => {
      expect(text).to.include('Update');
    });
  });

  it('should handle dynamic list updates with proper ARIA attributes', () => {
    // Verify list container has proper ARIA attributes
    cy.get('[data-testid="dynamic-list"]').should('have.attr', 'role', 'list');

    // Add item to list
    cy.get('[data-testid="add-item-button"]').click();

    // Verify new item is announced
    cy.get('[aria-live="polite"]').should('contain', 'Item added');

    // Verify list items have proper roles
    cy.get('[data-testid="dynamic-list"] [role="listitem"]').should('have.length.greaterThan', 0);

    // Verify aria-label or aria-describedby on new items
    cy.get('[data-testid="dynamic-list"] [role="listitem"]').last().should(($item) => {
      expect($item).to.have.attr('aria-label').or.have.attr('aria-describedby');
    });
  });

  it('should announce form validation errors dynamically', () => {
    // Verify error region exists
    cy.get('[role="alert"]').should('exist');

    // Submit form with invalid data
    cy.get('[data-testid="form-input"]').type('invalid');
    cy.get('[data-testid="form-submit"]').click();

    // Verify error is announced
    cy.get('[role="alert"]').should('contain', 'error');
    cy.get('[role="alert"]').should('have.attr', 'aria-live', 'assertive');

    // Verify input has aria-invalid
    cy.get('[data-testid="form-input"]').should('have.attr', 'aria-invalid', 'true');

    // Fix error and verify announcement
    cy.get('[data-testid="form-input"]').clear().type('valid@example.com');
    cy.get('[data-testid="form-submit"]').click();

    cy.get('[role="alert"]').should('contain', 'success');
  });

  it('should handle edge case of rapid successive updates', () => {
    // Trigger multiple rapid updates
    for (let i = 0; i < 5; i++) {
      cy.get('[data-testid="update-button"]').click();
    }

    // Verify aria-live region exists and is not overwhelmed
    cy.get('[aria-live="polite"]').should('exist');

    // Verify last update is present
    cy.get('[aria-live="polite"]').invoke('text').then((text) => {
      expect(text.length).to.be.greaterThan(0);
    });

    // Run accessibility checks to ensure no violations
    cy.checkA11y();
  });

  it('should announce content removal with appropriate messaging', () => {
    // Verify initial content exists
    cy.get('[data-testid="removable-item"]').should('exist');

    // Remove content
    cy.get('[data-testid="remove-button"]').click();

    // Verify removal is announced
    cy.get('[aria-live="polite"]').should('contain', 'removed');

    // Verify content is actually removed
    cy.get('[data-testid="removable-item"]').should('not.exist');
  });
});
